/// <summary>
/// Post load.
/// </summary>
public void postLoad()
{
    next postLoad();

    if (this.METInventDimId)
    {
        InventDim inventDim = InventDim::findInLegalEntity(this.METInventDimId, this.DataAreaId);

        if (inventDim)
        {
            this.Configuration = inventDim.configId;
            this.Size = inventDim.InventSizeId;
            this.Color = inventDim.InventColorId;
            this.Style = inventDim.InventStyleId;
            this.Site = inventDim.InventSiteId;
            this.Warehouse = inventDim.InventLocationId;
            this.Location = inventDim.wMSLocationId;
            this.InventoryStatus = inventDim.InventStatusId;
            this.LicensePlate = inventDim.LicensePlateId;
            this.BatchNumber = inventDim.inventBatchId;
            this.SerialNumber = inventDim.inventSerialId;
            this.Owner = inventDim.InventOwnerId_RU;
        }
    }
}

/// <summary>
/// Update entity datasource.
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
/// <returns>boolean</returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);       

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();

        GUPPriceTermJournalTable journal = trans.gupPriceTermJournalTable();

        if (journal.Status == GUPDisabledEnabled::Disabled)
        {                
            journal.Status = GUPDisabledEnabled::Enabled;
            journal.update();
        }
    }

    return ret;
}

/// <summary>
