/// <returns>boolean</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();

        GUPPriceTermJournalTable journal = trans.gupPriceTermJournalTable();

        if (journal.Status == GUPDisabledEnabled::Disabled)
        {
            journal.Status = GUPDisabledEnabled::Enabled;
            journal.update();
        }
    }

    return ret;
}
